const input = $input.first()?.json ?? {};
const body = input.body ?? input;
const headers = input.headers ?? {};
const rawPayload = body.payload ?? input.payload ?? {};
let payload = rawPayload;
if (typeof rawPayload === 'string') { try { payload = JSON.parse(rawPayload); } catch (e) { payload = {}; } }
const authorization = (headers.authorization || headers.Authorization || input.authorization || '').toString().trim();
const requestId = (headers['x-request-id'] || headers['X-Request-Id'] || input.request_id || ('req-' + Date.now())).toString();
const actorEmail = (headers['x-actor-email'] || headers['X-Actor-Email'] || input.actor_email || '').toString();
const idempotencyKey = (headers['idempotency-key'] || headers['Idempotency-Key'] || input.idempotency_key || '').toString();
return [{ json: { action: String(body.action || input.action || '').trim(), payload, authorization, request_id: requestId, actor_email: actorEmail, idempotency_key: idempotencyKey, received_at: new Date().toISOString() } }];

const expected = String($env.ADMIN_BACKOFFICE_TOKEN || 'REPLACE_ME').trim();
const authorization = String($json.authorization || '').trim();
const token = authorization.replace(/^Bearer\s+/i, '').trim();
return [{ json: { ...$json, auth_ok: Boolean(expected && token && token === expected) } }];

const p = $json.payload || {};
const valid = Boolean(p.prospect_id && p.triggered_by);
return [{ json: { ...$json, valid, validation_error: valid ? null : 'prospect_id et triggered_by sont requis.' } }];

